parser.script:
// 鬼片网：卡片/详情/分集解析与基准正则一一对应；播放页 var now= 直链。
function gpAbs(base, u) {
  u = String(u == null ? '' : u).trim();
  if (!u) return '';
  if (u.indexOf('//') === 0) return 'https:' + u;
  if (/^https?:\/\//i.test(u)) return u;
  var b = gpStrip(base);
  return u.indexOf('/') === 0 ? b + u : b + '/' + u;
}
function gpStrip(base) { return String(base || '').replace(/\/+$/, ''); }
function gpClean(text) {
  return String(text == null ? '' : text).replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&quot;/gi, '"').replace(/&#39;/g, "'").replace(/\u3000/g, ' ').replace(/\s+/g, ' ').trim();
}
function gpItems(raw, context) {
  var html = String(raw || '');
  var out = [], seen = {};
  var re = /<a class="video-link" href="\/nv\/(\d+)\.html"[^>]*title="([^"]*)"([\s\S]*?)<\/a>/gi;
  var m;
  while ((m = re.exec(html))) {
    var id = m[1];
    if (seen[id]) continue;
    seen[id] = 1;
    var chunk = m[3].slice(0, 800);
    var cover = '';
    var cm = /data-(?:original|background)="([^"]+)"/i.exec(chunk);
    if (cm) cover = gpAbs(context.baseUrl, cm[1]);
    var remark = '';
    var rm = /<div class="video-duration">([\s\S]*?)<\/div>/i.exec(chunk);
    if (rm) remark = gpClean(rm[1]);
    var title = gpClean(m[2]);
    if (!title) continue;
    out.push({ id: id, title: title.slice(0, 512), cover: cover, detailUrl: '/nv/' + id + '.html', status: remark.slice(0, 64) });
    if (out.length > 500) break;
  }
  return out;
}
function parseList(raw, context) { return gpItems(raw, context); }
function parseCategory(raw, context) { return gpItems(raw, context); }
function parseSearch(raw, context) {
  var html = String(raw || '');
  var keyword = String((context && context.keyword) || '').toLowerCase();
  var out = [], seen = {};
  var items = html.match(/<item>[\s\S]*?<\/item>/gi) || [];
  for (var i = 0; i < items.length && out.length < 30; i++) {
    var tm = /<title>\s*(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?\s*<\/title>/i.exec(items[i]);
    var lm = /\/nv\/(\d+)\.html/i.exec(items[i]);
    if (!tm || !lm) continue;
    var title = gpClean(tm[1]);
    if (!title || title.toLowerCase().indexOf(keyword) < 0) continue;
    var id = lm[1];
    if (seen[id]) continue;
    seen[id] = 1;
    out.push({ id: id, title: title.slice(0, 512), cover: '', detailUrl: '/nv/' + id + '.html' });
  }
  return out;
}
function gpDetail(raw, context) {
  var html = String(raw || '');
  var title = '';
  var tm = /<h1 class="media-title[^"]*">([\s\S]*?)<\/h1>/i.exec(html);
  if (tm) title = gpClean(tm[1]);
  if (!title) {
    var tt = /<title>([\s\S]*?)<\/title>/i.exec(html);
    if (tt) title = gpClean(tt[1]);
  }
  if (!title) return { id: (context && context.id) || '' };
  var cover = '';
  var c1 = /<div class="detail-img"><img[^>]+src="([^"]+)"/i.exec(html);
  var c2 = /<div class="detail-cover[^"]*"[^>]*data-original="([^"]+)"/i.exec(html);
  if (c1) cover = gpAbs(context.baseUrl, c1[1]);
  else if (c2) cover = gpAbs(context.baseUrl, c2[1]);
  var desc = '';
  var dm = /简介：([\s\S]*?)<\/li>/i.exec(html);
  if (dm) desc = gpClean(dm[1]);
  var tags = [];
  var ym = /年份：<span>([\s\S]*?)<\/span>/i.exec(html);
  if (ym && gpClean(ym[1])) tags.push(gpClean(ym[1]) + '年');
  var drm = /导演：([\s\S]*?)<\/span>/i.exec(html);
  if (drm && gpClean(drm[1])) tags.push('导演 ' + gpClean(drm[1]).slice(0, 32));
  var am = /主演：([\s\S]*?)<\/span>/i.exec(html);
  if (am && gpClean(am[1])) tags.push('主演 ' + gpClean(am[1]).slice(0, 48));
  var sm = /状态：([\s\S]*?)<\/span>/i.exec(html);
  return {
    id: String((context && context.id) || ''),
    title: title.slice(0, 512),
    cover: cover,
    description: desc.slice(0, 12000),
    tags: tags,
    status: sm ? gpClean(sm[1]).slice(0, 64) : ''
  };
}
function parseDetail(raw, context) { return gpDetail(raw, context); }
function parseEpisodes(raw, context) {
  var html = String(raw || '');
  if (!html) return [];
  var lineIDs = [];
  var tabRe = /<li class="swiper-slide ewave-tab[^"]*" data-target="#(ewave-playlist-\d+)">([^<]+)<\/li>/gi;
  var tab;
  while ((tab = tabRe.exec(html))) {
    if (lineIDs.indexOf(tab[1]) < 0) lineIDs.push(tab[1]);
  }
  var best = null;
  for (var i = 0; i < lineIDs.length; i++) {
    var marker = 'id="' + lineIDs[i] + '"';
    var start = html.indexOf(marker);
    if (start < 0) continue;
    var segment = html.slice(start + marker.length);
    var next = segment.indexOf('id="ewave-playlist');
    if (next >= 0) segment = segment.slice(0, next);
    var eps = [];
    var epSeen = {};
    var epRe = /<li><a title='([^']*)' href='([^']+)'/gi;
    var ep;
    while ((ep = epRe.exec(segment))) {
      if (epSeen[ep[2]]) continue;
      epSeen[ep[2]] = 1;
      eps.push([ep[1], ep[2]]);
    }
    if (!best || eps.length > best.length) { best = eps; }
  }
  if (!best) {
    best = [];
    var epRe2 = /<li><a title='([^']*)' href='([^']+)'/gi;
    var ep2, seen2 = {};
    while ((ep2 = epRe2.exec(html))) {
      if (seen2[ep2[2]]) continue;
      seen2[ep2[2]] = 1;
      best.push([ep2[1], ep2[2]]);
    }
  }
  var out = [];
  for (var k = 0; k < best.length; k++) {
    var href = best[k][1];
    if (href.indexOf('//') === 0) href = 'https:' + href;
    else if (href.indexOf('/') === 0) href = gpStrip(context.baseUrl) + href;
    if (!/guipianwu\.com/i.test(href) || !/\/play\/\d+-\d+-\d+\.html/i.test(href)) continue;
    var title = gpClean(best[k][0]);
    var number = 0;
    var nm = /(\d+)/.exec(title);
    if (nm) number = parseInt(nm[1], 10);
    if (!number || number <= 0) number = out.length + 1;
    out.push({ id: String(number), title: title || ('第' + number + '集'), number: number, url: href });
  }
  return out;
}
var GP_NOW = /var\s+now\s*=\s*["']([^"']+)["']/i;
var GP_M3U_URLS = [];
function gpExtractNow(html) {
  var m = GP_NOW.exec(String(html || ''));
  var url = m ? m[1] : '';
  if (!url) {
    var any = /https?:\/\/[^"'\s<>]+\.(?:m3u8|mp4)(?:\?[^"'\s<>]*)?/i.exec(html);
    url = any ? any[0] : '';
  }
  if (url && url.indexOf('//') === 0) url = 'https:' + url;
  return url;
}
// 播放页 URL 三段式 {id}-{line}-{ep}：换 line 段即换线路。
// 从本页收集其余线路同集数的播放页地址（聚合资源站常见部分线路 CDN 已失效）。
function gpSiblingPages(html, pageUrl, context) {
  var pm = /play\/([0-9]+)-([0-9]+)-([0-9]+)\.html/i.exec(String(pageUrl || ''));
  if (!pm) return [];
  var id = pm[1], curLine = pm[2], ep = pm[3];
  var seen = {}, out = [];
  var re = /play\/([0-9]+)-([0-9]+)-([0-9]+)\.html/gi, m;
  while ((m = re.exec(String(html || '')))) {
    if (m[1] !== id || m[2] === curLine || seen[m[2]]) continue;
    seen[m[2]] = 1;
    out.push(gpAbs(context.baseUrl, '/play/' + id + '-' + m[2] + '-' + ep + '.html'));
    if (out.length >= 4) break;
  }
  return out;
}
function parseVideo(raw, context) {
  var now = gpExtractNow(raw);
  GP_M3U_URLS = [];
  if (now) GP_M3U_URLS.push(now);
  var sibs = gpSiblingPages(raw, context.url, context);
  if (!sibs.length) return now || '';
  // 两跳探活：跳1 取其余线路播放页，跳2 并发探测各线路 m3u8，回第一个存活的。
  return {
    __meta: true,
    __fetchUrls: sibs,
    __fetchResponseType: 'text',
    __processor: 'gpPickPageNow'
  };
}
function gpPickPageNow(raw, context) {
  var bodies = Array.isArray(raw) ? raw : [raw];
  for (var i = 0; i < bodies.length; i++) {
    var u = gpExtractNow(bodies[i]);
    if (u && GP_M3U_URLS.indexOf(u) < 0) GP_M3U_URLS.push(u);
  }
  if (GP_M3U_URLS.length <= 1) return GP_M3U_URLS[0] || '';
  return {
    __meta: true,
    __fetchUrls: GP_M3U_URLS.slice(0),
    __fetchResponseType: 'text',
    __processor: 'gpPickLive'
  };
}
function gpPickLive(raw, context) {
  var bodies = Array.isArray(raw) ? raw : [raw];
  for (var i = 0; i < bodies.length; i++) {
    var b = String(bodies[i] == null ? '' : bodies[i]);
    if (/^\s*#EXTM3U/.test(b) || b.indexOf('#EXTINF') >= 0) return GP_M3U_URLS[i] || '';
  }
  return GP_M3U_URLS[0] || '';
}
